package main
type Point struct{ X int }
type P *Point
type Box int
func (b Box) Replace(x int) int {b=Box(x);return int(b)}
func receiver() int { b:=Box(3); f:=Box.Replace; return f(b,7)+int(b) }
func namedPtr() int {v:=Point{3}; var p P=&v; p.X=5; return v.X+(*p).X}
func exact() int {const k=(1.0/3)*3; const n=((1<<200)+3)-(1<<200); return int(k+n)}
func skipped() int {const(a=iota;_=42;b=iota);return b-a}
func twice(x int) int { return x*2 }
func overlap() int { s:=[]int{1,2,3,4}; t:=append(s[:2],s[1:]...); return 10*len(t)+t[2] }
func overlapCopy() int { s:=[]int{1,2,3,4}; copy(s[1:],s[:3]); return 10*s[2]+s[3] }
func drain() int { c:=make(chan int,1); c<-3; close(c); x,ok:=<-c; if !ok{return 99}; y,ok:=<-c; if ok {return 98}; return 10*x+y }
func blocked() int { c:=make(chan int); c<-3; return 123 }
func bytesCopied() int { s:=[]byte("AZ"); copy(s,"a"); return int(s[0])+int(s[1]) }
func mapAlias() int { m:=map[int]int{1:3}; n:=m; n[1]=7; return twice(m[1]) }
func unknown(flag bool) int { s:=[]int{1}; if flag {s[0]=2}; return s[0] }
